// Prüft das LLM-Ergebnis. Unbekannte Kategorie -> NICHT zurückschreiben (Knut lehnt null ab).
const MIN_KONFIDENZ = 0.6;
const namen = $('Kategorien bündeln').first().json.namen;
const r = $input.first().json.output ?? $input.first().json;
const gueltig = namen.includes(r.kategorie);
const konfidenz = typeof r.konfidenz === 'number' ? Math.max(0, Math.min(1, r.konfidenz)) : undefined;
return [{ json: {
  gueltig,
  geruecht_id: Number($('Webhook').first().json.body.geruecht_id),
  kategorie: r.kategorie,
  kernaussage: String(r.kernaussage ?? '').slice(0, 500),
  konfidenz,
  begruendung: String(r.begruendung ?? '').slice(0, 1000),
  manuell_pruefen: konfidenz === undefined || konfidenz < MIN_KONFIDENZ,
  fehler: gueltig ? '' : 'Unbekannte Kategorie "' + r.kategorie + '" – gültig: ' + namen.join(', ')
}}];
